import java.util.*;interface NotificationChannel{void send(Student s,Notice n);}class Student{String name,department;List<NotificationChannel> channels=new ArrayList<>();Student(String n,String d){name=n;department=d;}void addChannel(NotificationChannel c){channels.add(c);}}class Notice{String title;Set<String> departments;Notice(String t,Set<String>d){if(t==null||t.trim().isEmpty()||d==null||d.isEmpty())throw new IllegalArgumentException();title=t;departments=new HashSet<>(d);}}class EmailChannel implements NotificationChannel{public void send(Student s,Notice n){System.out.println("[Email → "+s.name+"] "+n.title);}}class SmsChannel implements NotificationChannel{public void send(Student s,Notice n){System.out.println("[SMS → "+s.name+"] "+n.title);}}class AppChannel implements NotificationChannel{public void send(Student s,Notice n){System.out.println("[App → "+s.name+"] "+n.title);}}class NoticeBoard{List<Student> students=new ArrayList<>();void addStudent(Student s){students.add(s);}void post(Notice n){for(Student s:students)if(n.departments.contains(s.department))for(NotificationChannel c:s.channels)c.send(s,n);}}public class Main{public static void main(String[]a){}}